// Cybersecurity Skills Browser — vanilla JS, no build step.
// Loads docs/data.json (generated by tools/build-browser-data.py),
// renders a 3-pane browser, and filters in-memory.

const REPO_URL = "https://github.com/mukul975/Anthropic-Cybersecurity-Skills";
const BRANCH = "main";

const state = {
  skills: [],
  subdomainSelections: new Set(),
  tagSelections: new Set(),
  frameworkSelections: new Set(),  // "attack" | "nist_csf" | "owasp"
  query: "",
  activeSkill: null,
};

// Security-domain acronyms that should render uppercase rather than Title Case.
// Add entries as you notice mis-cased terms in the UI ("Jwt" → "JWT", etc).
const ACRONYMS = new Set([
  "api", "soc", "siem", "soar", "ioc", "iam", "owasp", "saml", "oauth",
  "tls", "ssl", "dns", "http", "https", "url", "jwt", "xss", "csrf", "ssrf",
  "xxe", "sql", "rce", "rdp", "smb", "ntlm", "tcp", "udp", "wmi", "ldap",
  "mfa", "vpn", "ad", "aws", "gcp", "ip", "ai", "ml", "cli", "ci", "cd",
  "ttp", "dfir", "edr", "xdr", "mdr", "waf", "ips", "ids", "nist", "csf",
  "iot", "ot", "ics", "scada", "pki", "ca", "lfi", "csp", "hsts", "cors",
  "fido", "totp", "yara", "stix", "taxii", "misp", "rat", "apt", "c2",
  "lnk", "pdf", "elf", "pe", "exe", "dll", "vm", "icmp", "snmp", "ipsec",
  "dhcp", "ntp", "smtp", "imap", "ftp", "ssh", "rbac", "abac", "uba", "ueba",
  "k8s", "ec2", "s3", "iam", "kms", "vpc", "elb", "lambda", "gke", "aks",
]);

function prettifyName(name) {
  return name.split("-").map((w) => {
    if (!w) return "";
    if (ACRONYMS.has(w.toLowerCase())) return w.toUpperCase();
    return w.charAt(0).toUpperCase() + w.slice(1);
  }).join(" ");
}

// Safely insert text into an element, wrapping case-insensitive matches of
// `query` in <mark>. Uses DOM nodes (no innerHTML) so it's XSS-safe.
function highlightInto(target, text, query) {
  target.replaceChildren();
  if (!query) {
    target.append(document.createTextNode(text));
    return;
  }
  const lower = text.toLowerCase();
  const q = query.toLowerCase();
  let cursor = 0;
  let idx = lower.indexOf(q);
  if (idx === -1) {
    target.append(document.createTextNode(text));
    return;
  }
  while (idx !== -1) {
    if (idx > cursor) target.append(document.createTextNode(text.slice(cursor, idx)));
    const mark = document.createElement("mark");
    mark.textContent = text.slice(idx, idx + q.length);
    target.append(mark);
    cursor = idx + q.length;
    idx = lower.indexOf(q, cursor);
  }
  if (cursor < text.length) target.append(document.createTextNode(text.slice(cursor)));
}

// ────────────────────────────────────────────────────────────────────────────
// FILTER COMPOSITION — user contribution point
// ────────────────────────────────────────────────────────────────────────────
//
// Given a skill and the current filter state, return true if the skill should
// be visible in the results list. This is the heart of the UX.
//
// Design decisions you need to make:
//
//   1. Within a single category (e.g. user checks BOTH "cloud-security" AND
//      "threat-hunting" subdomains), should we show skills matching EITHER
//      (union/OR) or BOTH (intersection/AND)?
//      → Convention: OR within a category. A skill has exactly one subdomain,
//        so AND would always return 0 results for subdomain anyway. For tags,
//        OR is more forgiving and matches user mental model of "show me
//        anything tagged X or Y".
//
//   2. Across categories (subdomain + tag + framework + search), should we
//      AND them together (must match all categories) or OR (match any)?
//      → Convention: AND across categories. "Cloud security skills tagged
//        with kerberos" is what users expect, not "cloud OR kerberos".
//
//   3. Empty filter category — does an unchecked category mean "match
//      everything" or "match nothing"?
//      → Convention: empty means no constraint. If the user hasn't picked any
//        subdomain, we don't filter on subdomain at all.
//
//   4. Search query — substring across name/description/tags? Or just name?
//      → Up to you. Substring across multiple fields is friendlier but
//        slower; with 754 skills it's fine.
//
// Implementation hint (5-10 lines):
//   - For each active category, check whether the skill satisfies it.
//   - Return false as soon as ANY active category fails (AND-across).
//   - Within a category, .some() on the user's selections (OR-within).
//   - Treat state.query as case-insensitive substring search.
//
function matchesFilters(skill) {
  // Rule: OR within a category, AND across categories. Empty category = no constraint.

  if (state.subdomainSelections.size > 0 && !state.subdomainSelections.has(skill.subdomain)) {
    return false;
  }

  if (state.tagSelections.size > 0 && !skill.tags.some((t) => state.tagSelections.has(t))) {
    return false;
  }

  if (state.frameworkSelections.size > 0) {
    const hasAny = (state.frameworkSelections.has("attack")   && skill.attack.length   > 0)
                || (state.frameworkSelections.has("nist_csf") && skill.nist_csf.length > 0)
                || (state.frameworkSelections.has("owasp")    && skill.owasp.length    > 0);
    if (!hasAny) return false;
  }

  if (state.query) {
    const hay = [
      skill.name,
      skill.description,
      skill.tags.join(" "),
      skill.attack.join(" "),
    ].join(" ").toLowerCase();
    if (!hay.includes(state.query)) return false;
  }

  return true;
}
// ────────────────────────────────────────────────────────────────────────────

async function loadData() {
  const res = await fetch("data.json");
  if (!res.ok) throw new Error(`Failed to load data.json: ${res.status}`);
  return res.json();
}

function renderSubdomainFilters(subdomains) {
  const ul = document.getElementById("subdomain-filters");
  ul.replaceChildren();
  for (const [name, count] of Object.entries(subdomains)) {
    const li = document.createElement("li");
    const label = document.createElement("label");
    const cb = document.createElement("input");
    cb.type = "checkbox";
    cb.dataset.subdomain = name;
    const nameSpan = document.createElement("span");
    nameSpan.textContent = name;
    const countSpan = document.createElement("span");
    countSpan.className = "tag-count";
    countSpan.textContent = String(count);
    label.append(cb, nameSpan, countSpan);
    li.append(label);
    ul.append(li);
  }
  ul.addEventListener("change", (e) => {
    const cb = e.target;
    if (!cb.dataset.subdomain) return;
    if (cb.checked) state.subdomainSelections.add(cb.dataset.subdomain);
    else state.subdomainSelections.delete(cb.dataset.subdomain);
    render();
  });
}

function renderTagFilters(topTags) {
  const ul = document.getElementById("tag-filters");
  ul.replaceChildren();
  for (const [tag, count] of Object.entries(topTags)) {
    const li = document.createElement("li");
    const label = document.createElement("label");
    const cb = document.createElement("input");
    cb.type = "checkbox";
    cb.dataset.tag = tag;
    const tagSpan = document.createElement("span");
    tagSpan.textContent = tag;
    const countSpan = document.createElement("span");
    countSpan.className = "tag-count";
    countSpan.textContent = String(count);
    label.append(cb, tagSpan, countSpan);
    li.append(label);
    ul.append(li);
  }
  ul.addEventListener("change", (e) => {
    const cb = e.target;
    if (!cb.dataset.tag) return;
    if (cb.checked) state.tagSelections.add(cb.dataset.tag);
    else state.tagSelections.delete(cb.dataset.tag);
    render();
  });
}

function wireFrameworkFilters() {
  document.querySelectorAll('input[data-framework]').forEach((cb) => {
    cb.addEventListener("change", () => {
      if (cb.checked) state.frameworkSelections.add(cb.dataset.framework);
      else state.frameworkSelections.delete(cb.dataset.framework);
      render();
    });
  });
}

function wireSearch() {
  const input = document.getElementById("search");
  let timer = null;
  input.addEventListener("input", () => {
    // Show/hide the (×) button immediately, even before the debounced render.
    updateSearchClearVisibility();
    clearTimeout(timer);
    timer = setTimeout(() => {
      state.query = input.value.trim().toLowerCase();
      render();
    }, 120);
  });
}

function clearAllFilters() {
  state.subdomainSelections.clear();
  state.tagSelections.clear();
  state.frameworkSelections.clear();
  state.query = "";
  document.getElementById("search").value = "";
  document.querySelectorAll('.filter-list input[type="checkbox"]').forEach((cb) => {
    cb.checked = false;
  });
  // Also clear the "filter within" inputs and unhide all filter list items.
  document.querySelectorAll(".filter-within").forEach((input) => { input.value = ""; });
  document.querySelectorAll(".filter-list li.hidden-by-filter").forEach((li) => {
    li.classList.remove("hidden-by-filter");
  });
  updateSearchClearVisibility();
  render();
}

function wireClear() {
  document.getElementById("clear").addEventListener("click", clearAllFilters);
}

function updateSearchClearVisibility() {
  const btn = document.getElementById("search-clear");
  btn.hidden = !document.getElementById("search").value;
}

function wireSearchClear() {
  const btn = document.getElementById("search-clear");
  btn.addEventListener("click", () => {
    const input = document.getElementById("search");
    input.value = "";
    state.query = "";
    btn.hidden = true;
    input.focus();
    render();
  });
}

// Search-within-filter: type to narrow long checkbox lists by substring
// match on the visible label text. Doesn't change filter state — only what's
// shown in the sidebar.
function wireFilterWithin() {
  document.querySelectorAll(".filter-within").forEach((input) => {
    input.addEventListener("input", () => {
      const q = input.value.trim().toLowerCase();
      const ul = document.getElementById(input.dataset.target);
      if (!ul) return;
      ul.querySelectorAll("li").forEach((li) => {
        const labelText = li.textContent.toLowerCase();
        const match = !q || labelText.includes(q);
        li.classList.toggle("hidden-by-filter", !match);
      });
    });
  });
}

// Active filter chips: a horizontal strip above the results that mirrors
// state.* selections. Each chip has an × that removes just that one filter.
// Lets users see and undo without scrolling back to the sidebar.
function renderActiveChips() {
  const bar = document.getElementById("active-chips");
  bar.replaceChildren();

  const chips = [];
  for (const v of state.subdomainSelections) chips.push({ kind: "subdomain", value: v, label: v });
  for (const v of state.tagSelections)       chips.push({ kind: "tag",       value: v, label: v });
  for (const v of state.frameworkSelections) {
    const label = { attack: "ATT&CK", nist_csf: "NIST CSF", owasp: "OWASP" }[v] || v;
    chips.push({ kind: "framework", value: v, label });
  }
  if (state.query) chips.push({ kind: "query", value: state.query, label: state.query });

  if (chips.length === 0) {
    bar.hidden = true;
    return;
  }
  bar.hidden = false;

  for (const c of chips) {
    const chip = document.createElement("span");
    chip.className = "active-chip";

    const prefix = document.createElement("span");
    prefix.className = "label-prefix";
    prefix.textContent = {
      subdomain: "Subdomain:",
      tag: "Tag:",
      framework: "Framework:",
      query: "Search:",
    }[c.kind];

    const text = document.createElement("span");
    text.textContent = c.label;

    const x = document.createElement("button");
    x.type = "button";
    x.setAttribute("aria-label", `Remove ${c.kind} filter`);
    x.textContent = "×";
    x.addEventListener("click", () => removeFilter(c.kind, c.value));

    chip.append(prefix, text, x);
    bar.append(chip);
  }
}

function removeFilter(kind, value) {
  if (kind === "subdomain") {
    state.subdomainSelections.delete(value);
    const cb = document.querySelector(`input[data-subdomain="${CSS.escape(value)}"]`);
    if (cb) cb.checked = false;
  } else if (kind === "tag") {
    state.tagSelections.delete(value);
    const cb = document.querySelector(`input[data-tag="${CSS.escape(value)}"]`);
    if (cb) cb.checked = false;
  } else if (kind === "framework") {
    state.frameworkSelections.delete(value);
    const cb = document.querySelector(`input[data-framework="${CSS.escape(value)}"]`);
    if (cb) cb.checked = false;
  } else if (kind === "query") {
    state.query = "";
    document.getElementById("search").value = "";
    updateSearchClearVisibility();
  }
  render();
}

function renderResults(visible) {
  const ul = document.getElementById("results-list");
  document.getElementById("count").textContent = `${visible.length} of ${state.skills.length}`;
  ul.replaceChildren();

  if (visible.length === 0) {
    const empty = document.createElement("div");
    empty.className = "empty-state";
    const msg = document.createElement("div");
    msg.textContent = "No skills match the current filters.";
    empty.append(msg);
    const btn = document.createElement("button");
    btn.type = "button";
    btn.textContent = "Clear all filters";
    btn.addEventListener("click", clearAllFilters);
    empty.append(btn);
    ul.append(empty);
    return;
  }

  // Hard cap render to 250 for performance; user can refine to narrow.
  const slice = visible.slice(0, 250);
  for (const s of slice) {
    const li = document.createElement("li");
    li.dataset.name = s.name;
    if (state.activeSkill && s.name === state.activeSkill.name) {
      li.classList.add("active");
    }

    const nameDiv = document.createElement("div");
    nameDiv.className = "skill-name";
    // Highlight the query if it matches the display name; otherwise the
    // match came from a tag/description/technique-id and we just show the
    // pretty name unmarked.
    const pretty = prettifyName(s.name);
    highlightInto(nameDiv, pretty, state.query);

    const metaDiv = document.createElement("div");
    metaDiv.className = "skill-meta";
    const subSpan = document.createElement("span");
    subSpan.className = "subdomain";
    subSpan.textContent = s.subdomain || "—";
    metaDiv.append(subSpan);
    if (s.attack.length) {
      const a = document.createElement("span");
      a.textContent = `ATT&CK ×${s.attack.length}`;
      metaDiv.append(a);
    }
    if (s.nist_csf.length) {
      const a = document.createElement("span");
      a.textContent = `CSF ×${s.nist_csf.length}`;
      metaDiv.append(a);
    }

    li.append(nameDiv, metaDiv);
    li.addEventListener("click", () => showDetail(s));
    ul.append(li);
  }

  if (visible.length > slice.length) {
    const more = document.createElement("div");
    more.className = "empty-state";
    more.textContent = `Showing first ${slice.length}. Narrow filters to see more.`;
    ul.append(more);
  }
}

function makeChips(values, extraClass = "") {
  const wrap = document.createElement("dd");
  wrap.className = "chips";
  if (!values.length) {
    wrap.textContent = "—";
    return wrap;
  }
  for (const v of values) {
    const chip = document.createElement("span");
    chip.className = extraClass ? `chip ${extraClass}` : "chip";
    chip.textContent = v;
    wrap.append(chip);
  }
  return wrap;
}

function makeRow(label, dd) {
  const dt = document.createElement("dt");
  dt.textContent = label;
  return [dt, dd];
}

function makeTextRow(label, value) {
  const dd = document.createElement("dd");
  dd.textContent = value || "—";
  return makeRow(label, dd);
}

function showDetail(skill) {
  state.activeSkill = skill;
  document.querySelectorAll("#results-list li").forEach((li) => {
    li.classList.toggle("active", li.dataset.name === skill.name);
  });

  const detail = document.getElementById("detail");
  detail.replaceChildren();

  const h2 = document.createElement("h2");
  h2.className = "detail-title";
  h2.textContent = prettifyName(skill.name);
  detail.append(h2);

  const slug = document.createElement("code");
  slug.className = "detail-slug";
  slug.textContent = skill.name;
  detail.append(slug);

  const desc = document.createElement("p");
  desc.className = "desc";
  desc.textContent = skill.description;
  detail.append(desc);

  const dl = document.createElement("dl");
  dl.className = "meta-grid";
  dl.append(...makeTextRow("Subdomain", skill.subdomain));
  dl.append(...makeRow("Tags", makeChips(skill.tags)));
  if (skill.attack.length) dl.append(...makeRow("MITRE ATT&CK", makeChips(skill.attack, "framework")));
  if (skill.nist_csf.length) dl.append(...makeRow("NIST CSF", makeChips(skill.nist_csf, "framework")));
  if (skill.owasp.length) dl.append(...makeRow("OWASP", makeChips(skill.owasp, "framework")));
  dl.append(...makeTextRow("Author", skill.author));
  dl.append(...makeTextRow("Version", skill.version));
  detail.append(dl);

  if (skill.when_to_use) {
    const h3 = document.createElement("h3");
    h3.textContent = "When to use";
    const box = document.createElement("div");
    box.className = "when-to-use";
    box.textContent = skill.when_to_use;
    detail.append(h3, box);
  }

  const link = document.createElement("a");
  link.className = "source-link";
  // path comes from build-browser-data.py and is a fixed pattern "skills/<name>/SKILL.md";
  // both segments are kebab-case so URL-encoding is a no-op, but apply it for safety.
  link.href = `${REPO_URL}/blob/${BRANCH}/${skill.path.split("/").map(encodeURIComponent).join("/")}`;
  link.target = "_blank";
  link.rel = "noopener";
  link.textContent = "View full SKILL.md on GitHub →";
  detail.append(link);
}

// ── URL state ──────────────────────────────────────────────────────────────
// Hash format: #sub=cloud-security,threat-hunting&tag=kerberos&fw=attack&q=lateral
// Lets users share a filtered view by URL. We use history.replaceState (not
// pushState) so filter clicks don't pollute the back-button history.

function serializeStateToHash() {
  const parts = [];
  if (state.subdomainSelections.size) {
    parts.push("sub=" + [...state.subdomainSelections].map(encodeURIComponent).join(","));
  }
  if (state.tagSelections.size) {
    parts.push("tag=" + [...state.tagSelections].map(encodeURIComponent).join(","));
  }
  if (state.frameworkSelections.size) {
    parts.push("fw=" + [...state.frameworkSelections].join(","));
  }
  if (state.query) {
    parts.push("q=" + encodeURIComponent(state.query));
  }
  const hash = parts.length ? "#" + parts.join("&") : "";
  if (location.hash !== hash) {
    history.replaceState(null, "", hash || location.pathname + location.search);
  }
}

function applyHashToState() {
  const hash = location.hash.startsWith("#") ? location.hash.slice(1) : "";
  if (!hash) return;
  for (const part of hash.split("&")) {
    const eq = part.indexOf("=");
    if (eq === -1) continue;
    const key = part.slice(0, eq);
    const raw = part.slice(eq + 1);
    const values = raw.split(",").map(decodeURIComponent).filter(Boolean);
    if (key === "sub") values.forEach((v) => state.subdomainSelections.add(v));
    else if (key === "tag") values.forEach((v) => state.tagSelections.add(v));
    else if (key === "fw") values.forEach((v) => state.frameworkSelections.add(v));
    else if (key === "q") state.query = values[0] || "";
  }
}

function syncCheckboxesToState() {
  document.querySelectorAll("input[data-subdomain]").forEach((cb) => {
    cb.checked = state.subdomainSelections.has(cb.dataset.subdomain);
  });
  document.querySelectorAll("input[data-tag]").forEach((cb) => {
    cb.checked = state.tagSelections.has(cb.dataset.tag);
  });
  document.querySelectorAll("input[data-framework]").forEach((cb) => {
    cb.checked = state.frameworkSelections.has(cb.dataset.framework);
  });
  document.getElementById("search").value = state.query;
}

// ── Keyboard navigation ────────────────────────────────────────────────────
// ↑/↓ walks the visible results list (without wraparound — clamping is more
// predictable for keyboard users than wrap). Enter selects the first result
// when nothing is active yet (handy after typing a search).

function wireKeyboard() {
  document.addEventListener("keydown", (e) => {
    // Don't hijack typing in a multi-line / rich text field.
    const tag = (e.target.tagName || "").toLowerCase();
    if (tag === "textarea" || e.target.isContentEditable) return;
    if (e.key !== "ArrowDown" && e.key !== "ArrowUp" && e.key !== "Enter") return;

    const items = Array.from(document.querySelectorAll("#results-list li[data-name]"));
    if (items.length === 0) return;

    const activeIdx = items.findIndex((li) => li.classList.contains("active"));

    if (e.key === "Enter") {
      if (activeIdx === -1) {
        e.preventDefault();
        items[0].click();
      }
      return;
    }

    e.preventDefault();
    const next = e.key === "ArrowDown"
      ? Math.min((activeIdx < 0 ? -1 : activeIdx) + 1, items.length - 1)
      : Math.max((activeIdx < 0 ? items.length : activeIdx) - 1, 0);

    items[next].click();
    items[next].scrollIntoView({ block: "nearest" });
  });
}

function render() {
  const visible = state.skills.filter(matchesFilters);
  renderActiveChips();
  renderResults(visible);
  serializeStateToHash();
}

async function main() {
  let data;
  try {
    data = await loadData();
  } catch (e) {
    document.getElementById("count").textContent = `Error: ${e.message}`;
    return;
  }
  state.skills = data.skills;
  renderSubdomainFilters(data.subdomains);
  renderTagFilters(data.top_tags);
  applyHashToState();       // populate state.* from #hash before wiring inputs
  syncCheckboxesToState();  // reflect that state into the freshly-built UI
  updateSearchClearVisibility();
  wireFrameworkFilters();
  wireSearch();
  wireSearchClear();
  wireFilterWithin();
  wireClear();
  wireKeyboard();
  render();
}

main();
